// ─── File: MigrationDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MigrationDemo {

    private static final Logger log = Logger.getLogger(MigrationDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Canary migration of transfer fee logic at " + BANK_NAME);

        OldTransferCalculator oldCalc = new OldTransferCalculator();
        NewTransferCalculator newCalc = new NewTransferCalculator();
        MigrationRouter router = new MigrationRouter(oldCalc, newCalc, 20, true);

        // A set of real transfers between Rajesh and Priya. The last one is forced to mismatch.
        router.route(new TransferRequest("TXF-A", "SAV2001", "CUR3001", new BigDecimal("50000"), false));
        router.route(new TransferRequest("TXF-B", "CUR3001", "SAV2001", new BigDecimal("10000"), false));
        router.route(new TransferRequest("TXF-C", "SAV2001", "CUR3001", new BigDecimal("75000"), false));
        router.route(new TransferRequest("TXF-D", "SAV2001", "CUR3001", new BigDecimal("20000"), true));

        log.info(() -> "Rollout mismatches detected: " + router.getMismatchCount()
                + ". Only increase rollout percent when mismatches stay at zero.");
    }
}

// ─── Would be in model/TransferRequest.java in a real project ───
class TransferRequest {
    private final String id;
    private final String from;
    private final String to;
    private final BigDecimal amount;
    private final boolean forceBug; // simulates the new service behaving differently

    TransferRequest(String id, String from, String to, BigDecimal amount, boolean forceBug) {
        this.id = id;
        this.from = from;
        this.to = to;
        this.amount = amount;
        this.forceBug = forceBug;
    }

    String getId() { return id; }
    BigDecimal getAmount() { return amount; }
    boolean isForceBug() { return forceBug; }
}

// ─── Would be in calc/OldTransferCalculator.java in a real project ───
// The trusted legacy logic: fee is 0.1% of the amount.
class OldTransferCalculator {
    BigDecimal fee(TransferRequest req) {
        return req.getAmount().multiply(new BigDecimal("0.001"));
    }
}

// ─── Would be in calc/NewTransferCalculator.java in a real project ───
// The new service. Should match the old logic. forceBug simulates a regression.
class NewTransferCalculator {
    BigDecimal fee(TransferRequest req) {
        if (req.isForceBug()) {
            return req.getAmount().multiply(new BigDecimal("0.002")); // wrong — double fee
        }
        return req.getAmount().multiply(new BigDecimal("0.001"));
    }
}

// ─── Would be in router/MigrationRouter.java in a real project ───
class MigrationRouter {
    private static final Logger log = Logger.getLogger(MigrationRouter.class.getName());
    private final OldTransferCalculator oldCalc;
    private final NewTransferCalculator newCalc;
    private final int rolloutPercent;
    private final boolean verifyParity;
    private int requestCounter = 0;
    private int mismatchCount = 0;

    MigrationRouter(OldTransferCalculator oldCalc, NewTransferCalculator newCalc,
                    int rolloutPercent, boolean verifyParity) {
        this.oldCalc = oldCalc;
        this.newCalc = newCalc;
        this.rolloutPercent = rolloutPercent;
        this.verifyParity = verifyParity;
    }

    BigDecimal route(TransferRequest req) {
        requestCounter++;
        BigDecimal oldFee = oldCalc.fee(req);

        if (verifyParity) {
            BigDecimal newFee = newCalc.fee(req);
            if (oldFee.compareTo(newFee) != 0) {
                mismatchCount++;
                log.severe(() -> "PARITY MISMATCH on " + req.getId() + ": old=" + oldFee
                        + " new=" + newFee + ". Serving OLD result, blocking rollout increase.");
                return oldFee;
            }
        }

        boolean useNew = (requestCounter * 100) % 100 < rolloutPercent
                || (requestCounter % (100 / Math.max(1, rolloutPercent)) == 0);
        if (useNew) {
            log.info(() -> req.getId() + " served by NEW service (parity verified), fee=" + oldFee);
        } else {
            log.info(() -> req.getId() + " served by OLD service, fee=" + oldFee);
        }
        return oldFee;
    }

    int getMismatchCount() { return mismatchCount; }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
